tinymce.PluginManager.add('validation', function(editor, url) {
	var guideLineSel = '';
	var markSelGuideLine = '';
	var defaultGuidLine = '';
	var guidelineItems = [];

	function validate(){
		var language = navigator.language || navigator.userLanguage;
		var code = language.substring(0,2);

		var request = {	'lang': code,
	            	'content': editor.getContent({format : 'text'}),
		        'guidelines': guideLineSel ,
		        'fragment'  : true
			};
			var idName ='acheck'+editor.id;

			var loaddialog = dijit.Dialog({
			title: "Validating",
			content : "&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<img src='/html/images/icons/round-progress-bar.gif' alt='loading'/>"
			});
			loaddialog.show();

			function createValidationResult( response ){

			loaddialog.hide(); loaddialog.destroy();

			var div = document.createElement("div");
			div.id = idName;
			div.setAttribute("align", "center");
			div.setAttribute("style", "height: 340px;overflow: scroll; width: auto;overflow-x: hidden;overflow-y:auto;");
			var text = "" ;

			// TinyMCE 8 removed `editor.getLang(key, default)` (the old namespaced i18n
			// lookup). `editor.translate(text)` is the modern equivalent: it looks up `text`
			// itself as the key and returns it unchanged if no translation is registered — see
			// langs/*.js, now keyed by these same English default strings.
			var msgText = editor.translate('Validation complete! ');

			if( response.errors.length > 0 ){
				msgText += response.errors.length + editor.translate(' Errors Found!');
			}
			else {
			  msgText += editor.translate('No errors found!');
			}
			if( response.errors.length > 0 ){
				text  += "<p style='color:red;'><strong>"+editor.translate('Accessibility Review  - Guideline: ')+"" + guideLineSel +" </strong> </p>";
				var testo = editor.translate('Description');
				text += "<table border='1' class='listingTable'>";
				text += "<tr> <th>Check ID </th>  "+
					"<th>"+testo+"</th>"+
					"<th>"+editor.translate('Row/Column')+"</th>"+
					"<th>"+editor.translate('Error Type')+"</th> </tr>";

				for ( var i = 0; i < response.errors.length; i++ ) {
					var error = response.errors[i];
					var modulo = (i+1)   % 2;
					var classValue ="1";
					if( modulo == 0 ){
						classValue = "2";
					}
					var classType = "alternate_"+classValue;
						var idRow = "elem_"+i;
					text += "<tr id='"+idRow+"' class='"+classType + "' >";
					text += "<td class='titleCellDiv'>" +error.check.check_id + "</td>";
					text += "<td> " + error.check.err +"( " + error.check.description +" ) </td>";

					text += "<td>" + error.line_number + "/" + error.col_number + "</td>";
					text += "<td>" + error.check.confidenceEnum +"</td>";
					text += "</tr> ";
				}
				text += "</table>";
				div.innerHTML = text;
				var dialog = dijit.Dialog({
					title: msgText,
					content : div,
					style: "width: 640px;"
				});
				dialog.show();
			}
			}
			try{

			ACheckerDWR.validate(request ,createValidationResult);

			} catch(e){
			alert(e);
			}
	}

	function createGuideline( response  ){
		guidelineItems = [];
		tinymce.each (response, function (o) {
			if( guideLineSel == '' && o.defaultGuideLine )
			{
				defaultGuidLine = o.title;
			}
			guidelineItems.push({ title: o.title, abbr: o.abbr });
		});
	}

	ACheckerDWR.getSupportedGudelines(createGuideline);

	// TinyMCE 8: the old `type: 'splitbutton'` + a `menu` array mutated in place by the async
	// DWR callback, plus a separate `onshow` handler marking the active item, are replaced by
	// `addMenuButton`'s `fetch(callback)` — called fresh every time the dropdown opens, so it
	// always reflects the latest `guidelineItems` and computes the active guideline inline via
	// `togglemenuitem`'s `active` flag (no separate onshow pass needed). There was never a
	// distinct "main button" action in the original (no top-level `onclick`), so a plain
	// menu button — always opens the dropdown — is the closer match to a splitbutton with no
	// primary action, not a real split button.
	editor.ui.registry.addMenuButton('validation', {
		icon: 'accessibility-check',
		tooltip: 'Achecker Validation',
		fetch: function(callback) {
			var activeTitle = markSelGuideLine || defaultGuidLine;
			var items = [
				{ type: 'menuitem', text: 'Validation Guidelines', enabled: false, onAction: function() {} }
			].concat(guidelineItems.map(function(guideline) {
				return {
					type: 'togglemenuitem',
					text: guideline.title,
					active: guideline.title === activeTitle,
					onAction: function() {
						guideLineSel = guideline.abbr;
						markSelGuideLine = guideline.title;
						validate();
					}
				};
			}));
			callback(items);
		}
	});
});
